const e="General Information",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/social-sciences-humanities/general-regulations/general-information/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/social-sciences-humanities/general-regulations/general-information/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:3,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"3 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"Student Classification",sh:8}},{key:"unenumeratedSection",params:{title:"Student Status",sh:8}},{key:"unenumeratedSection",params:{title:"Grading Policies",sh:8}}],overflow:0}]}},a=0,s=2027,i=[{type:"SECTION",title:"Student Classification",creditsRequired:8,minRequirementCount:1,requirements:[],notes:["Regular student—Students who are admitted to a degree or certificate program.","Special student—Nonmatriculated students who are enrolled in College of Social Sciences and Humanities graduate courses on a less than full-time basis (fewer than 8 semester hours per semester). Special students may earn up to 12 semester hours over time. Special students who do not register for four consecutive semesters (excluding summer semester) may be subject to review and possible withdrawal by the college. Graduate certificates and degrees cannot be conferred upon students in special student status. In keeping with university regulations, international students cannot be admitted as special students.","Doctoral degree candidate—Doctoral students who have completed departmental, college, and university requirements except for dissertation."]},{type:"SECTION",title:"Student Status",creditsRequired:8,minRequirementCount:1,requirements:[],notes:["For academic purposes, a graduate student is considered a full-time student if enrolled in a minimum of 8 semester hours of credit for the semester, with the following exceptions:","Continued registration in the CSSH is contingent upon receiving all official transcripts and test scores within 30 days of matriculation. Please note that you may be asked to provide us with these if you did not include official copies in your application."]},{type:"SECTION",title:"Grading Policies",creditsRequired:8,minRequirementCount:1,requirements:[],notes:["Grading policies applying to all students may be found in the Academic Catalog.","In the CSSH, not more than two courses or 8 semester hours of credit, whichever is greater, may be repeated to satisfy the requirements for the degree. Only such repeats will be counted in calculating the cumulative grade-point average. No grade changes are permitted after the end of the final examination period one calendar year from the semester in which the student registered for the course. This includes the clearance of incomplete grades. In calculating the overall cumulative average, all graduate-level coursework completed at the time of clearance for graduation will be counted.","Students cannot elect a satisfactory/unsatisfactory grading scheme for CSSH courses unless the course grading scheme is designated satisfactory/unsatisfactory."]}],n={name:e,metadata:t,totalCreditsRequired:a,yearVersion:s,requirementSections:i};export{n as default,t as metadata,e as name,i as requirementSections,a as totalCreditsRequired,s as yearVersion};
